#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_process_guess_correct_guess_guesses_size_less_than_25(void) {
    struct game_instance game;
    const char *word = "apple";
    char guess = 'a';

    init_game_instance(&game, word);
    TEST_ASSERT_EQUAL_INT(0, game.guesses_size);
    TEST_ASSERT_EQUAL_INT(0, game.incorrect);

    // Initialize hidden array to underscores (as expected by process_guess)
    for (int i = 0; i < game.size; i++) {
        game.hidden[i] = '_';
    }

    int result = process_guess(&game, guess);

    TEST_ASSERT_EQUAL_INT(1, result);
    TEST_ASSERT_EQUAL_INT(1, game.guesses_size);
    TEST_ASSERT_EQUAL_INT('a', game.guesses[0]);
    TEST_ASSERT_EQUAL_INT(0, game.incorrect);
    TEST_ASSERT_EQUAL_INT('a', game.hidden[0]);
    TEST_ASSERT_EQUAL_INT('p', game.hidden[1]);
    TEST_ASSERT_EQUAL_INT('p', game.hidden[2]);
    TEST_ASSERT_EQUAL_INT('l', game.hidden[3]);
    TEST_ASSERT_EQUAL_INT('e', game.hidden[4]);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_process_guess_correct_guess_guesses_size_less_than_25);
    return UNITY_END();
}

