typedef struct {
    int pipe_read_fd;
    int pipe_write_fd;
    int saved_stdout_fd;
} capture_t;

// Function: capture_stdout_start (from helper pool)
void *capture_stdout_start(void) {
    capture_t *cap = malloc(sizeof(capture_t));
    if (!cap) return NULL;

    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }

    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = pipefd[1];

    cap->saved_stdout_fd = dup(STDOUT_FILENO);
    if (cap->saved_stdout_fd == -1) {
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }

    if (dup2(cap->pipe_write_fd, STDOUT_FILENO) == -1) {
        close(cap->saved_stdout_fd);
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }

    return cap;
}

// Function: capture_stdout_stop (from helper pool)
char *capture_stdout_stop(void *cap) {
    if (!cap) return NULL;
    capture_t *capture = (capture_t *)cap;

    fflush(stdout);
    close(capture->pipe_write_fd);

    if (dup2(capture->saved_stdout_fd, STDOUT_FILENO) == -1) {
        close(capture->saved_stdout_fd);
        close(capture->pipe_read_fd);
        free(capture);
        return NULL;
    }
    close(capture->saved_stdout_fd);

    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(capture->pipe_read_fd);
        free(capture);
        return NULL;
    }

    ssize_t bytes_read;
    while ((bytes_read = read(capture->pipe_read_fd, buffer + total_read,
                               buffer_capacity - total_read - 1)) > 0) {
        total_read += bytes_read;
        if (total_read >= buffer_capacity - 1) {
            buffer_capacity *= 2;
            char *new_buffer = realloc(buffer, buffer_capacity);
            if (!new_buffer) {
                free(buffer);
                close(capture->pipe_read_fd);
                free(capture);
                return NULL;
            }
            buffer = new_buffer;
        }
    }

    buffer[total_read] = '\0';
    close(capture->pipe_read_fd);
    free(capture);
    return buffer;
}

